{
  "version": "Notebook/1.0",
  "items": [
    {
      "type": 1,
      "content": {
        "json": "# Azure update and software inventory\nSCCM-inspired reporting from Change Tracking and Inventory data in Log Analytics."
      },
      "name": "header"
    },
    {
      "type": 9,
      "content": {
        "version": "KqlParameterItem/1.0",
        "parameters": [
          {
            "id": "2dd0f518-6916-49ea-a92f-87fc13142a98",
            "version": "KqlParameterItem/1.0",
            "name": "TimeRange",
            "label": "History range",
            "type": 4,
            "isRequired": true,
            "typeSettings": {
              "selectableValues": [
                {
                  "durationMs": 2592000000
                },
                {
                  "durationMs": 7776000000
                },
                {
                  "durationMs": 15552000000
                },
                {
                  "durationMs": 31536000000
                },
                {
                  "durationMs": 63072000000
                }
              ],
              "allowCustom": true
            },
            "timeContext": {
              "durationMs": 7776000000
            },
            "value": {
              "durationMs": 7776000000
            }
          },
          {
            "id": "79cc279d-2037-4ae7-ad41-a8527205ad8e",
            "version": "KqlParameterItem/1.0",
            "name": "InventoryFreshness",
            "label": "Current inventory window",
            "type": 2,
            "isRequired": true,
            "jsonData": "[{\"value\":\"1d\",\"label\":\"24 hours\"},{\"value\":\"2d\",\"label\":\"2 days\"},{\"value\":\"7d\",\"label\":\"7 days\"},{\"value\":\"14d\",\"label\":\"14 days\"}]",
            "value": "2d"
          },
          {
            "id": "ad4bd442-f183-42c7-a8a9-4a0676910f20",
            "version": "KqlParameterItem/1.0",
            "name": "RequiredKBs",
            "label": "Required KB baseline",
            "type": 1,
            "isRequired": false,
            "quote": "'",
            "value": ""
          },
          {
            "id": "d8825c22-3097-4272-90f5-19756913b3fa",
            "version": "KqlParameterItem/1.0",
            "name": "ComputerSearch",
            "label": "Computer contains",
            "type": 1,
            "isRequired": false,
            "quote": "'",
            "value": ""
          },
          {
            "id": "83b43a99-f447-408e-a02e-f8840fd34149",
            "version": "KqlParameterItem/1.0",
            "name": "SoftwareSearch",
            "label": "Software contains",
            "type": 1,
            "isRequired": false,
            "quote": "'",
            "value": ""
          }
        ],
        "style": "pills",
        "queryType": 0,
        "resourceType": "microsoft.operationalinsights/workspaces"
      },
      "name": "report-parameters"
    },
    {
      "type": 3,
      "content": {
        "version": "KqlItem/1.0",
        "query": "let MachineInventory = materialize(\n    ConfigurationData\n    | where ConfigDataType =~ \"Software\"\n    | summarize LastInventory = max(TimeGenerated) by Computer\n);\nlet CurrentSoftware = materialize(\n    ConfigurationData\n    | where ConfigDataType =~ \"Software\"\n    | where TimeGenerated >= ago({InventoryFreshness})\n);\nunion\n    (MachineInventory | summarize Value = count() | extend Metric = \"Reporting computers\"),\n    (MachineInventory | summarize Value = countif(LastInventory >= ago({InventoryFreshness})) | extend Metric = \"Current inventory\"),\n    (MachineInventory | summarize Value = countif(LastInventory < ago({InventoryFreshness})) | extend Metric = \"Stale inventory\"),\n    (CurrentSoftware | summarize Value = dcountif(strcat(Computer, \"|\", SoftwareName), SoftwareType =~ \"Patch\") | extend Metric = \"Installed update records\")\n| project Metric, Value",
        "size": 4,
        "title": "Inventory summary",
        "timeContext": {
          "durationMs": 94608000000
        },
        "queryType": 0,
        "resourceType": "microsoft.operationalinsights/workspaces",
        "crossComponentResources": [
          "__WORKSPACE_RESOURCE_ID__"
        ],
        "visualization": "tiles",
        "tileSettings": {
          "titleContent": {
            "columnMatch": "Metric",
            "formatter": 1
          },
          "leftContent": {
            "columnMatch": "Value",
            "formatter": 12,
            "formatOptions": {
              "palette": "auto"
            }
          },
          "showBorder": true
        }
      },
      "name": "inventory-summary"
    },
    {
      "type": 1,
      "content": {
        "json": "## Inventory health\nComparable to SCCM scan-state and inventory-recency reports."
      },
      "name": "inventory-health-heading"
    },
    {
      "type": 3,
      "content": {
        "version": "KqlItem/1.0",
        "query": "ConfigurationData\n| where ConfigDataType =~ \"Software\"\n| summarize LastInventory = max(TimeGenerated), ResourceId = take_any(_ResourceId) by Computer\n| where isempty({ComputerSearch}) or Computer contains {ComputerSearch}\n| extend SubscriptionId = tostring(split(ResourceId, \"/\")[2])\n| extend InventoryAgeDays = datetime_diff(\"day\", now(), LastInventory)\n| extend InventoryState = iff(LastInventory >= ago({InventoryFreshness}), \"Current\", \"Stale\")\n| project Computer, InventoryState, LastInventory, InventoryAgeDays, SubscriptionId, ResourceId\n| sort by InventoryState asc, LastInventory desc",
        "size": 0,
        "title": "Inventory state by computer",
        "timeContext": {
          "durationMs": 94608000000
        },
        "queryType": 0,
        "resourceType": "microsoft.operationalinsights/workspaces",
        "crossComponentResources": [
          "__WORKSPACE_RESOURCE_ID__"
        ],
        "visualization": "table"
      },
      "name": "inventory-health"
    },
    {
      "type": 1,
      "content": {
        "json": "## Baseline compliance\n> **Inventory-derived:** Enter comma-separated KB identifiers, such as `KB5030219,KB5030310`. A computer is compliant only when every baseline KB is present in its current inventory. This is not SCCM or Update Manager required/deployment state."
      },
      "name": "baseline-compliance-heading"
    },
    {
      "type": 3,
      "content": {
        "version": "KqlItem/1.0",
        "query": "let RequiredUpdates = materialize(\n    print Items = split({RequiredKBs}, \",\")\n    | mv-expand RequiredKB = Items to typeof(string)\n    | extend RequiredKB = toupper(replace_string(RequiredKB, \" \", \"\"))\n    | where RequiredKB matches regex @\"^KB[0-9]{6,8}$\"\n    | distinct RequiredKB\n);\nlet Computers = materialize(\n    ConfigurationData\n    | where ConfigDataType =~ \"Software\"\n    | where TimeGenerated >= ago({InventoryFreshness})\n    | summarize LastInventory = max(TimeGenerated), ResourceId = take_any(_ResourceId) by Computer\n    | where isempty({ComputerSearch}) or Computer contains {ComputerSearch}\n);\nlet Installed = materialize(\n    ConfigurationData\n    | where ConfigDataType =~ \"Software\" and SoftwareType =~ \"Patch\"\n    | where TimeGenerated >= ago({InventoryFreshness})\n    | extend KB = toupper(extract(@\"KB[0-9]{6,8}\", 0, SoftwareName))\n    | where isnotempty(KB)\n    | distinct Computer, KB\n);\nlet Compliance = materialize(\n    Computers\n    | extend JoinKey = 1\n    | join kind=inner (RequiredUpdates | extend JoinKey = 1) on JoinKey\n    | join kind=leftouter (Installed | extend IsInstalled = true) on Computer, $left.RequiredKB == $right.KB\n    | extend IsInstalled = iff(isnull(IsInstalled), false, IsInstalled)\n    | summarize RequiredUpdates = count(), InstalledUpdates = countif(IsInstalled) by Computer\n    | extend ComplianceState = iff(RequiredUpdates == InstalledUpdates, \"Compliant\", \"Noncompliant\")\n);\nunion\n    (Compliance | summarize Value = todouble(countif(ComplianceState == \"Compliant\")) | extend Metric = \"Compliant computers\"),\n    (Compliance | summarize Value = todouble(countif(ComplianceState == \"Noncompliant\")) | extend Metric = \"Noncompliant computers\"),\n    (Compliance | summarize TotalComputers = count(), CompliantComputers = countif(ComplianceState == \"Compliant\") | project Value = iff(TotalComputers == 0, 0.0, round(100.0 * CompliantComputers / TotalComputers, 1)) | extend Metric = \"Compliance percent\"),\n    (print Value = todouble(toscalar(RequiredUpdates | count)) | extend Metric = \"Baseline updates\")\n| project Metric, Value",
        "size": 3,
        "title": "Compliance 1 - Overall compliance",
        "timeContext": {
          "durationMs": 94608000000
        },
        "queryType": 0,
        "resourceType": "microsoft.operationalinsights/workspaces",
        "crossComponentResources": [
          "__WORKSPACE_RESOURCE_ID__"
        ],
        "visualization": "tiles",
        "tileSettings": {
          "titleContent": {
            "columnMatch": "Metric",
            "formatter": 1
          },
          "leftContent": {
            "columnMatch": "Value",
            "formatter": 12,
            "formatOptions": {
              "palette": "auto"
            }
          },
          "showBorder": true
        }
      },
      "name": "overall-baseline-compliance"
    },
    {
      "type": 3,
      "content": {
        "version": "KqlItem/1.0",
        "query": "let RequiredUpdates = materialize(\n    print Items = split({RequiredKBs}, \",\")\n    | mv-expand RequiredKB = Items to typeof(string)\n    | extend RequiredKB = toupper(replace_string(RequiredKB, \" \", \"\"))\n    | where RequiredKB matches regex @\"^KB[0-9]{6,8}$\"\n    | distinct RequiredKB\n);\nlet Computers = materialize(\n    ConfigurationData\n    | where ConfigDataType =~ \"Software\"\n    | where TimeGenerated >= ago({InventoryFreshness})\n    | summarize LastInventory = max(TimeGenerated), ResourceId = take_any(_ResourceId) by Computer\n    | where isempty({ComputerSearch}) or Computer contains {ComputerSearch}\n);\nlet Installed = materialize(\n    ConfigurationData\n    | where ConfigDataType =~ \"Software\" and SoftwareType =~ \"Patch\"\n    | where TimeGenerated >= ago({InventoryFreshness})\n    | extend KB = toupper(extract(@\"KB[0-9]{6,8}\", 0, SoftwareName))\n    | where isnotempty(KB)\n    | distinct Computer, KB\n);\nComputers\n| extend JoinKey = 1\n| join kind=inner (RequiredUpdates | extend JoinKey = 1) on JoinKey\n| join kind=leftouter (Installed | extend IsInstalled = true) on Computer, $left.RequiredKB == $right.KB\n| extend IsInstalled = iff(isnull(IsInstalled), false, IsInstalled)\n| summarize RequiredUpdates = count(), InstalledUpdates = countif(IsInstalled), MissingKBs = make_set_if(RequiredKB, IsInstalled == false, 100) by Computer, LastInventory, ResourceId\n| extend MissingUpdates = RequiredUpdates - InstalledUpdates\n| extend ComplianceState = iff(MissingUpdates == 0, \"Compliant\", \"Noncompliant\")\n| project Computer, ComplianceState, RequiredUpdates, InstalledUpdates, MissingUpdates, MissingKBs, LastInventory, ResourceId\n| sort by MissingUpdates desc, Computer asc",
        "size": 0,
        "title": "Compliance 5 and 7 - Computer compliance details",
        "timeContext": {
          "durationMs": 94608000000
        },
        "queryType": 0,
        "resourceType": "microsoft.operationalinsights/workspaces",
        "crossComponentResources": [
          "__WORKSPACE_RESOURCE_ID__"
        ],
        "visualization": "table"
      },
      "name": "computer-baseline-compliance"
    },
    {
      "type": 1,
      "content": {
        "json": "## Installed update inventory\nInventory equivalents for SCCM per-update and per-computer reports. Dates are observation times from `ConfigurationData`, not deployment timestamps."
      },
      "name": "installed-updates-heading"
    },
    {
      "type": 3,
      "content": {
        "version": "KqlItem/1.0",
        "query": "ConfigurationData\n| where ConfigDataType =~ \"Software\" and SoftwareType =~ \"Patch\"\n| where TimeGenerated >= ago({InventoryFreshness})\n| where isempty({ComputerSearch}) or Computer contains {ComputerSearch}\n| where isempty({SoftwareSearch}) or SoftwareName contains {SoftwareSearch}\n| extend KB = toupper(extract(@\"KB[0-9]{6,8}\", 0, SoftwareName))\n| extend UpdateIdentity = iff(isempty(KB), SoftwareName, KB)\n| summarize arg_max(TimeGenerated, SoftwareName, CurrentVersion, Publisher, Architecture) by Computer, UpdateIdentity\n| summarize InstalledComputers = dcount(Computer), Titles = make_set(SoftwareName, 5), Versions = make_set(CurrentVersion, 5), LastObserved = max(TimeGenerated) by UpdateIdentity, Publisher\n| project UpdateIdentity, Publisher, InstalledComputers, Titles, Versions, LastObserved\n| sort by InstalledComputers desc, UpdateIdentity asc",
        "size": 0,
        "title": "Compliance 2 and 3 - Installed update summary",
        "timeContext": {
          "durationMs": 94608000000
        },
        "queryType": 0,
        "resourceType": "microsoft.operationalinsights/workspaces",
        "crossComponentResources": [
          "__WORKSPACE_RESOURCE_ID__"
        ],
        "visualization": "table"
      },
      "name": "installed-update-summary"
    },
    {
      "type": 3,
      "content": {
        "version": "KqlItem/1.0",
        "query": "ConfigurationData\n| where ConfigDataType =~ \"Software\" and SoftwareType =~ \"Patch\"\n| where isempty({ComputerSearch}) or Computer contains {ComputerSearch}\n| extend KB = toupper(extract(@\"KB[0-9]{6,8}\", 0, SoftwareName))\n| where isnotempty(KB)\n| summarize FirstObserved = min(TimeGenerated), LastObserved = max(TimeGenerated) by Computer, KB\n| summarize Computers = dcount(Computer), Updates = dcount(KB) by bin(FirstObserved, 7d)\n| sort by FirstObserved asc",
        "size": 0,
        "title": "Historical update adoption by first observation",
        "timeContextFromParameter": "TimeRange",
        "queryType": 0,
        "resourceType": "microsoft.operationalinsights/workspaces",
        "crossComponentResources": [
          "__WORKSPACE_RESOURCE_ID__"
        ],
        "visualization": "timechart"
      },
      "name": "update-adoption-history"
    },
    {
      "type": 3,
      "content": {
        "version": "KqlItem/1.0",
        "query": "ConfigurationData\n| where ConfigDataType =~ \"Software\" and SoftwareType =~ \"Patch\"\n| where TimeGenerated >= ago({InventoryFreshness})\n| where isempty({ComputerSearch}) or Computer contains {ComputerSearch}\n| where isempty({SoftwareSearch}) or SoftwareName contains {SoftwareSearch}\n| extend KB = toupper(extract(@\"KB[0-9]{6,8}\", 0, SoftwareName))\n| summarize arg_max(TimeGenerated, *) by Computer, SoftwareName, CurrentVersion\n| project Computer, KB, SoftwareName, CurrentVersion, Publisher, Architecture, LastObserved = TimeGenerated, ResourceId = _ResourceId\n| sort by Computer asc, KB desc",
        "size": 0,
        "title": "Compliance 5 - Installed updates by computer",
        "timeContext": {
          "durationMs": 94608000000
        },
        "queryType": 0,
        "resourceType": "microsoft.operationalinsights/workspaces",
        "crossComponentResources": [
          "__WORKSPACE_RESOURCE_ID__"
        ],
        "visualization": "table"
      },
      "name": "installed-updates-by-computer"
    },
    {
      "type": 1,
      "content": {
        "json": "## Software inventory\nComparable to SCCM Software 01A, 02D, 02E, and 06A reports."
      },
      "name": "software-inventory-heading"
    },
    {
      "type": 3,
      "content": {
        "version": "KqlItem/1.0",
        "query": "ConfigurationData\n| where ConfigDataType =~ \"Software\" and SoftwareType in~ (\"Application\", \"Package\")\n| where TimeGenerated >= ago({InventoryFreshness})\n| where isempty({ComputerSearch}) or Computer contains {ComputerSearch}\n| where isempty({SoftwareSearch}) or SoftwareName contains {SoftwareSearch}\n| summarize arg_max(TimeGenerated, Publisher, Architecture, CurrentVersion) by Computer, SoftwareName\n| extend Publisher = iff(isempty(Publisher), \"Unknown\", Publisher)\n| summarize InstalledComputers = dcount(Computer), Versions = make_set(CurrentVersion, 8), Architectures = make_set(Architecture, 4), LastObserved = max(TimeGenerated) by SoftwareName, Publisher\n| project SoftwareName, Publisher, InstalledComputers, Versions, Architectures, LastObserved\n| top 250 by InstalledComputers desc",
        "size": 0,
        "title": "Software 01A and 06A - Installed software summary",
        "timeContext": {
          "durationMs": 94608000000
        },
        "queryType": 0,
        "resourceType": "microsoft.operationalinsights/workspaces",
        "crossComponentResources": [
          "__WORKSPACE_RESOURCE_ID__"
        ],
        "visualization": "table"
      },
      "name": "installed-software-summary"
    },
    {
      "type": 3,
      "content": {
        "version": "KqlItem/1.0",
        "query": "ConfigurationData\n| where ConfigDataType =~ \"Software\" and SoftwareType in~ (\"Application\", \"Package\")\n| where TimeGenerated >= ago({InventoryFreshness})\n| where isempty({ComputerSearch}) or Computer contains {ComputerSearch}\n| where isempty({SoftwareSearch}) or SoftwareName contains {SoftwareSearch}\n| summarize arg_max(TimeGenerated, *) by Computer, SoftwareName, CurrentVersion\n| project Computer, SoftwareName, CurrentVersion, Publisher, Architecture, SoftwareDescription, LastObserved = TimeGenerated, ResourceId = _ResourceId\n| sort by Computer asc, SoftwareName asc",
        "size": 0,
        "title": "Software 02D and 02E - Software by computer",
        "timeContext": {
          "durationMs": 94608000000
        },
        "queryType": 0,
        "resourceType": "microsoft.operationalinsights/workspaces",
        "crossComponentResources": [
          "__WORKSPACE_RESOURCE_ID__"
        ],
        "visualization": "table"
      },
      "name": "installed-software-by-computer"
    }
  ],
  "fallbackResourceIds": [
    "__WORKSPACE_RESOURCE_ID__"
  ],
  "isLocked": false
}
